"""Same-support distance/time versus balanced and shade-priority accessibility."""
from pathlib import Path
import json,shutil
import numpy as np,pandas as pd,geopandas as gpd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'output/plano_city/comparison';DEST=ROOT/'netlify_site/src';PROFILE=None
def run():
 OUT.mkdir(exist_ok=True);b=gpd.read_file(ROOT/'output/plano_city/accessibility/block_accessibility.gpkg');d=pd.read_csv(ROOT/'output/plano_city/accessibility/nearest_category_costs.csv',dtype={'GEOID20':str});old=pd.read_csv(ROOT/'output/plano_city/balanced_3km/accessibility/nearest_category_costs.csv',dtype={'GEOID20':str})
 profile=sorted(set(d.category)&set(old.category))
 def mean(table,col):
  p=table.pivot(index='GEOID20',columns='category',values=col)[profile];return p.mean(axis=1).where(p.notna().all(axis=1))
 b['time_min']=b.GEOID20.map(mean(d,'baseline_time_minutes'));b['shade_min']=b.GEOID20.map(mean(d,'min_friction_equivalent_minutes'));b['balanced_min']=b.GEOID20.map(mean(old,'min_friction_equivalent_minutes'));valid=b.HU100.gt(0)&b.access_snap_gap_m.le(100)&b[['time_min','shade_min','balanced_min']].notna().all(axis=1);v=b.loc[valid].copy();n=len(v)
 for key in ['time','shade','balanced']:v[key+'_pct']=100*(v[key+'_min'].rank(method='average')-1)/(n-1)
 v['rank_delta']=v.shade_pct-v.time_pct;v['friction_ratio']=v.shade_min/v.time_min.where(v.time_min>0)
 for field in ['time_pct','shade_pct','balanced_pct','rank_delta','friction_ratio']:b[field]=b.GEOID20.map(v.set_index('GEOID20')[field])
 top=lambda col:set(v.nsmallest(20,col).GEOID20);report={'profile':profile,'matched_residential_blocks':n,'same_support':'Identical graph, POI catalog, origins, residential and <=100 m connection filters. Each objective may choose a different nearest candidate within a category.','time_distance_equivalence':'At fixed 1.2 m/s, shortest walking-time and shortest-distance routes are equivalent. Mean shortest distance in meters = mean baseline minutes ×72.','original_balanced_vs_time_spearman':float(v.balanced_min.rank().corr(v.time_min.rank())),'shade_priority_vs_time_spearman':float(v.shade_min.rank().corr(v.time_min.rank())),'top20_overlap_balanced_time':len(top('balanced_min')&top('time_min')),'top20_overlap_shade_time':len(top('shade_min')&top('time_min')),'median_absolute_cost_percentile_change':float(v.rank_delta.abs().median()),'max_absolute_cost_percentile_change':float(v.rank_delta.abs().max()),'blocks_changing_by_10_percentile_points':int(v.rank_delta.abs().ge(10).sum()),'important':'Stronger shade coefficients and finer edge-local tree features are a chosen scenario, not evidence of improved human preference accuracy. Percentile-change colors use their own clearly labeled signed scale. Model-equivalent minutes are not actual walking duration.'}
 b.drop(columns='geometry').to_csv(OUT/'comparison_blocks.csv',index=False);(DEST/'data/friction_distance_comparison.csv').write_bytes((OUT/'comparison_blocks.csv').read_bytes());(DEST/'data/friction_distance_comparison.json').write_text(json.dumps(report,indent=2));(OUT/'method.json').write_text(json.dumps(report,indent=2))
 bg='#dce1dd';fig,axes=plt.subplots(1,2,figsize=(15,6));
 for ax,col,title in zip(axes,['time_pct','shade_pct'],['Walking time / distance only','Shade-priority friction']):
  b.plot(ax=ax,color=bg,linewidth=0);b.loc[valid].plot(ax=ax,column=col,cmap='RdYlBu_r',vmin=0,vmax=100,linewidth=0);ax.set_title(title);ax.set_axis_off()
 fig.colorbar(plt.cm.ScalarMappable(norm=plt.Normalize(0,100),cmap='RdYlBu_r'),ax=axes,shrink=.7,label='Cost percentile among matched residential blocks · blue lower, red higher');fig.text(.04,.025,'Same Plano origins, destinations and walking graph. Colors compare ranks, not raw minutes. Gray = excluded or incomplete.\nAll available destination categories; scenario coefficients are assumed, not learned preferences.',fontsize=9);fig.savefig(OUT/'distance_vs_friction_maps.png',dpi=180,bbox_inches='tight');plt.close(fig)
 limit=max(1,float(v.rank_delta.abs().max()));fig,ax=plt.subplots(figsize=(11,7));b.plot(ax=ax,color=bg,linewidth=0);b.loc[valid].plot(ax=ax,column='rank_delta',cmap='RdBu_r',vmin=-limit,vmax=limit,linewidth=0,legend=True,legend_kwds={'label':'Friction cost percentile minus time-only percentile','shrink':.7});ax.set_title('Where friction changes the ranking');ax.set_axis_off();fig.text(.04,.025,'Blue = ranks better with friction; red = ranks worse. White = little change.\nSigned percentile differences; this diverging scale is distinct from the cost maps.',fontsize=9);fig.tight_layout(rect=[0,.09,1,1]);fig.savefig(OUT/'friction_rank_change.png',dpi=180);plt.close(fig)
 fig,ax=plt.subplots(figsize=(9,7));sc=ax.scatter(v.time_min,v.shade_min,c=v.rank_delta,cmap='RdBu_r',vmin=-limit,vmax=limit,s=13,alpha=.65,linewidths=0);ax.set_xlabel('Mean shortest walking time to a category (ordinary minutes)');ax.set_ylabel('Mean shade-priority modeled cost (equivalent minutes)');ax.set_title('Does friction simply reproduce distance?');ax.grid(alpha=.15);fig.colorbar(sc,ax=ax,label='Change in cost percentile');ax.text(.04,.96,'Original balanced vs time: Spearman '+format(report['original_balanced_vs_time_spearman'],'.3f')+'\nShade-priority vs time: Spearman '+format(report['shade_priority_vs_time_spearman'],'.3f'),transform=ax.transAxes,va='top',bbox={'facecolor':'white','edgecolor':'#ddd'});fig.tight_layout();fig.savefig(OUT/'distance_friction_scatter.png',dpi=180);plt.close(fig)
 fig,ax=plt.subplots(figsize=(9,5));ax.hist(v.rank_delta,bins=40,color='#2c8077',edgecolor='white');ax.axvline(0,color='#222',linewidth=1);ax.set_xlabel('Change in cost percentile (friction minus time only)');ax.set_ylabel('Residential blocks');ax.set_title('How much do neighborhood rankings move?');fig.tight_layout();fig.savefig(OUT/'friction_change_distribution.png',dpi=180);plt.close(fig)
 plt.rcParams.update({'font.family':'Times New Roman','mathtext.fontset':'custom','mathtext.rm':'Times New Roman','mathtext.it':'Times New Roman:italic','mathtext.bf':'Times New Roman:bold'})
 fig,ax=plt.subplots(figsize=(15,2.2));ax.axis('off');ax.text(.5,.5,r'$w_e = \frac{L_e}{1.2}\left[1 + 6(1-C_e)^2(1+H_e) + Q_e\right]$',ha='center',va='center',fontsize=28);fig.savefig(OUT/'shade_priority_equation.png',dpi=200,bbox_inches='tight',facecolor='white');plt.close(fig)
 for name in ['distance_vs_friction_maps.png','friction_rank_change.png','distance_friction_scatter.png','friction_change_distribution.png','shade_priority_equation.png']:shutil.copy2(OUT/name,DEST/'figures'/name)
 print(json.dumps(report,indent=2));return report
if __name__=='__main__':run()
